module piano_note (
    input  wire [3:0]  idx,
    output reg [31:0]  step,
    output reg [0:0]   region
);
    always @(*) begin
        case (idx)
            4'd0 : begin step = 32'h00AF92EE; region = 1'd0; end  // C4        261.626 Hz
            4'd1 : begin step = 32'h00C51339; region = 1'd0; end  // D4        293.665 Hz
            4'd2 : begin step = 32'h00DD3595; region = 1'd0; end  // E4        329.628 Hz
            4'd3 : begin step = 32'h00EA5CF4; region = 1'd0; end  // F4        349.228 Hz
            4'd4 : begin step = 32'h0107104E; region = 1'd0; end  // G4        391.995 Hz
            4'd5 : begin step = 32'h0127476D; region = 1'd0; end  // A4        440.000 Hz
            4'd6 : begin step = 32'h014B7081; region = 1'd0; end  // B4        493.883 Hz
            4'd7 : begin step = 32'h015F25DC; region = 1'd1; end  // C5        523.251 Hz
            4'd8 : begin step = 32'h018A2672; region = 1'd1; end  // D5        587.330 Hz
            4'd9 : begin step = 32'h00BA039D; region = 1'd0; end
            4'd10: begin step = 32'h00D0CB35; region = 1'd0; end
            4'd11: begin step = 32'h00F84C8F; region = 1'd0; end
            4'd12: begin step = 32'h0116B4CE; region = 1'd0; end
